BEGIN;

CREATE TABLE IF NOT EXISTS ai_agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NULL REFERENCES tenants(id) ON DELETE CASCADE, agent_key text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')), risk_level text NOT NULL DEFAULT 'MEDIUM' CHECK (risk_level IN ('LOW','MEDIUM','HIGH','CRITICAL')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, agent_key));
CREATE TABLE IF NOT EXISTS ai_skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NULL REFERENCES tenants(id) ON DELETE CASCADE, skill_key text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', capabilities jsonb NOT NULL DEFAULT '[]'::jsonb, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, skill_key));
CREATE TABLE IF NOT EXISTS ai_tools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NULL REFERENCES tenants(id) ON DELETE CASCADE, tool_key text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', capability text NOT NULL, risk_level text NOT NULL DEFAULT 'LOW' CHECK (risk_level IN ('LOW','MEDIUM','HIGH','CRITICAL')), execution_mode text NOT NULL DEFAULT 'DIRECT' CHECK (execution_mode IN ('DIRECT','PROGRAMMATIC','APPROVAL_REQUIRED','BLOCKED')), enabled boolean NOT NULL DEFAULT true, schema jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, tool_key));
CREATE TABLE IF NOT EXISTS ai_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NULL REFERENCES tenants(id) ON DELETE CASCADE, policy_key text NOT NULL, name text NOT NULL, mode text NOT NULL DEFAULT 'APPROVAL' CHECK (mode IN ('AUTO','APPROVAL','BLOCK')), risk_level text NOT NULL DEFAULT 'HIGH' CHECK (risk_level IN ('LOW','MEDIUM','HIGH','CRITICAL')), conditions jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, policy_key));
CREATE TABLE IF NOT EXISTS ai_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, actor_user_id uuid NULL REFERENCES users(id) ON DELETE SET NULL, parent_run_id uuid NULL REFERENCES ai_runs(id) ON DELETE SET NULL, agent_key text NOT NULL, task text NOT NULL, status text NOT NULL DEFAULT 'PLANNING' CHECK (status IN ('PLANNING','WAITING_APPROVAL','RUNNING','SUCCEEDED','FAILED','CANCELLED')), risk_level text NOT NULL DEFAULT 'MEDIUM', plan jsonb NOT NULL DEFAULT '[]'::jsonb, result jsonb NOT NULL DEFAULT '{}'::jsonb, error text NULL, correlation_id text NULL, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz NULL, finished_at timestamptz NULL);
CREATE TABLE IF NOT EXISTS ai_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, tool_key text NOT NULL, action text NOT NULL, resource_type text NULL, resource_id text NULL, risk_level text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','EXECUTING','SUCCEEDED','FAILED','ROLLED_BACK','BLOCKED')), input jsonb NOT NULL DEFAULT '{}'::jsonb, output jsonb NOT NULL DEFAULT '{}'::jsonb, approval_required boolean NOT NULL DEFAULT true, approved_by uuid NULL REFERENCES users(id) ON DELETE SET NULL, approved_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz NULL);
CREATE INDEX IF NOT EXISTS ai_runs_tenant_created_idx ON ai_runs(tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ai_runs_tenant_correlation_idx ON ai_runs(tenant_id, correlation_id);
CREATE INDEX IF NOT EXISTS ai_actions_run_idx ON ai_actions(run_id, created_at);
CREATE INDEX IF NOT EXISTS ai_tools_tenant_capability_idx ON ai_tools(tenant_id, capability, enabled);
CREATE INDEX IF NOT EXISTS ai_skills_tenant_enabled_idx ON ai_skills(tenant_id, enabled);
COMMIT;
